<?php require __DIR__.'/../includes/bootstrap.php';require_admin();$pageTitle='Settings';$basePath='../';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();foreach(['fine_per_day','loan_days'] as $k){$v=$k==='fine_per_day'?max(0,(float)($_POST[$k]??0)):max(1,(int)($_POST[$k]??1));$pdo->prepare('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)')->execute([$k,(string)$v]);}audit($pdo,'Updated library settings');flash('success','Settings saved.');redirect('settings.php');}require __DIR__.'/../includes/layout_top.php';?><div class="panel narrow"><h3>Library rules</h3><p class="muted">These values control default due dates and overdue fine estimates.</p><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Fine per overdue day (₹)<input type="number" step="0.01" min="0" name="fine_per_day" value="<?=e(setting($pdo,'fine_per_day',10))?>"></label><label>Default loan period (days)<input type="number" min="1" name="loan_days" value="<?=e(setting($pdo,'loan_days',14))?>"></label><div class="wide"><button class="btn primary">Save settings</button></div></form></div><div class="panel narrow"><h3>Database backup</h3><p class="muted">Download a SQL backup using phpMyAdmin: select <b>library_management</b>, choose Export, then SQL.</p><a class="btn" href="http://localhost/phpmyadmin/" target="_blank" rel="noopener">Open phpMyAdmin</a></div><?php require __DIR__.'/../includes/layout_bottom.php';?>
